scan_para=function(id, r){
  if(id=="linkinput"){
    scan_impl(id, "#"+r+"#");}
  else{
   document.getElementById(id).value=r;
    }
};


//扫码返回刷新
Save_Data = function() {
   if($("#已扫数量").length){
    var index = plus.webview.getWebviewById("contentlist");
    mui.fire(index, "contentlist_local", {
        para: index.modelParams
    });}
}


//扫描后自动保存
scanAfterAction = function(r) {
  var dataCheck = $("#数据检查").val();
  
  // 数据检查
  if (dataCheck && dataCheck.trim() !== "") {
    alert(dataCheck);
    keep_focus("linkinput");
    return;
  } else {
    // 数据检查通过，执行自动保存
    recSave(globleServer, globleDmCode, globleDmNum, dataSumitScriptType, "","autoSave","autoSave");
  }
}

afterFunction = function (sta, id) {
    if (id == "autoSave" && sta == "autoSave")
        setTimeout(function () {
            keep_focus("linkinput");
        }, 100);
    if (sta == "linkquick12")
        reloadModelData()
};

beforeFunction=function(sta,id){
var a=$("#数据检查").val();
if(a!=""&&( sta=="new"||sta=="autoSave")){
alert(a);
return true;
}
else
{return false;}};

repeatTime=function(id){
   if(id=="linkpreprocess")
    return 10
    return 1
}

limitTimeAction=function(id){
   if(id=="linkpreprocess")
    alert("10秒内不可重复点击");
}
